/* AIVIC_FUNCTION_BUNDLE_START owner=detectMissingReportsAcrossYearBoundary exports=detectMissingReportsAcrossYearBoundary */
const __aivicBundle_28_detectMissingReportsAcrossYearBoundary = (() => {
  function detectMissingReportsAcrossYearBoundary(input: {
    reference_date: Date;
    target_date: Date;
    employees: Array<{
      employee_id: string;
      employee_name: string;
      submission_date: Date | null;
      is_submitted: boolean;
    }>;
    fiscal_year_boundary: {
      prev_year_final_day: Date;
      new_year_first_day: Date;
    };
  }): {
    target_date: Date;
    missing_report_count: number;
    missing_report_employees: Array<{
      employee_id: string;
      employee_name: string;
    }>;
    display_message: string;
  } {
    if (input["reference_date"] === undefined || input["reference_date"] === null) { throw new Error("reference_date is required"); }
    if (
      input.reference_date === undefined ||
      input.reference_date === null ||
      String(input.reference_date).trim() === ""
    ) {
      throw new Error("reference_date is required");
    }

    const {
      target_date,
      employees,
      fiscal_year_boundary: { prev_year_final_day, new_year_first_day },
    } = input;

    const missingReportEmployees = employees.filter((emp) => {
      if (!emp.is_submitted) {
        return true;
      }

      if (emp.submission_date === null) {
        return true;
      }

      if (emp.submission_date >= new_year_first_day) {
        return false;
      }

      if (emp.submission_date <= prev_year_final_day) {
        return true;
      }

      return true;
    });

    const missingReportCount = missingReportEmployees.length;

    const year = target_date.getFullYear();
    const month = String(target_date.getMonth() + 1).padStart(2, "0");
    const day = String(target_date.getDate()).padStart(2, "0");
    const displayMessage = `${year}年${month}月${day}日 ${missingReportCount}名 報告漏れ部員`;

    return {
      target_date,
      missing_report_count: missingReportCount,
      missing_report_employees: missingReportEmployees.map((emp) => ({
        employee_id: emp.employee_id,
        employee_name: emp.employee_name,
      })),
      display_message: displayMessage,
    };
  }
  return { detectMissingReportsAcrossYearBoundary };
})();
