/* AIVIC_FUNCTION_BUNDLE_START owner=sendMorningReportWithEmailNotification exports=sendMorningReportWithEmailNotification */
const __aivicBundle_43_sendMorningReportWithEmailNotification = (() => {
  async function sendMorningReportWithEmailNotification(reportData: {
    userId: string;
    senderEmail: string;
    managerEmail: string;
    yesterdayAccomplishment: string;
    todayPlan: string;
    challengesFaced: string;
    sentAt: Date;
    morningMeetingStartTime: Date;
  }): Promise<{ success: boolean; errorMessage?: string; status: string }> {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  
    if (!emailRegex.test(reportData.senderEmail)) {
      throw new Error(
        `送信者メールアドレスの形式が不正です: ${reportData.senderEmail}`
      );
    }
  
    if (!emailRegex.test(reportData.managerEmail)) {
      throw new Error(
        `部長メールアドレスの形式が不正です: ${reportData.managerEmail}`
      );
    }
  
    try {
      const confirmationEmailPayload = {
        userId: reportData.userId,
        senderEmail: reportData.senderEmail,
        managerEmail: reportData.managerEmail,
        yesterdayAccomplishment: reportData.yesterdayAccomplishment,
        todayPlan: reportData.todayPlan,
        challengesFaced: reportData.challengesFaced,
        sentAt: reportData.sentAt.toISOString(),
        morningMeetingStartTime: reportData.morningMeetingStartTime.toISOString(),
      };
  
      await Promise.all([
        fetch('/api/send-confirmation-email', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            recipient: reportData.senderEmail,
            type: 'reporter_confirmation',
            payload: confirmationEmailPayload,
          }),
        }),
        fetch('/api/send-confirmation-email', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            recipient: reportData.managerEmail,
            type: 'manager_notification',
            payload: confirmationEmailPayload,
          }),
        }),
      ]);
  
      return {
        success: true,
        status: '送信完了',
      };
    } catch (error) {
      const errorMsg =
        error instanceof Error ? error.message : '不明なエラーが発生しました';
      return {
        success: false,
        errorMessage: errorMsg,
        status: '失敗',
      };
    }
  }
  return { sendMorningReportWithEmailNotification };
})();
export const sendMorningReportWithEmailNotification = __aivicBundle_43_sendMorningReportWithEmailNotification.sendMorningReportWithEmailNotification;
/* AIVIC_FUNCTION_BUNDLE_END owner=sendMorningReportWithEmailNotification */

