/* AIVIC_FUNCTION_BUNDLE_START owner=sendReminderEmail exports=sendReminderEmail */
const __aivicBundle_166_sendReminderEmail = (() => {
  function sendReminderEmail(input: {
    recipientEmail: string;
    recipientName: string;
    subject: string;
    body: string;
    senderEmail: string;
  }): MailSendResult {
    const sentAt = new Date();
  
    // Email format validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(input.recipientEmail)) {
      return {
        success: false,
        emailsSent: 0,
        messageIds: [],
        sentAt,
        errorMessage: 'Invalid email format',
      };
    }
  
    if (!emailRegex.test(input.senderEmail)) {
      return {
        success: false,
        emailsSent: 0,
        messageIds: [],
        sentAt,
        errorMessage: 'Invalid sender email format',
      };
    }
  
    // Validate required fields
    if (
      !input.recipientEmail ||
      !input.recipientName ||
      !input.subject ||
      !input.body ||
      !input.senderEmail
    ) {
      return {
        success: false,
        emailsSent: 0,
        messageIds: [],
        sentAt,
        errorMessage: 'Missing required fields',
      };
    }
  
    // Generate message ID
    const { randomUUID } = require('crypto');
    const messageId = randomUUID();
  
    // Simulate successful email send
    return {
      success: true,
      emailsSent: 1,
      messageIds: [messageId],
      sentAt,
    };
  }
  return { sendReminderEmail };
})();
export const sendReminderEmail = __aivicBundle_166_sendReminderEmail.sendReminderEmail;
